output_text:
[
  {
    "id": "take_entry_cart",
    "text": "Customers are obliged to take the entry cart from the entry cart station before continuing their shopping trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "with_cart": "hasCart"
      },
      "events": {
        "entry_cart_pickup": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "entry_cart_pickup"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "Customers are forbidden to pick up shelf items unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers are forbidden to carry goods by hand while in the store.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "leave_cart_only_at_service_bay",
    "text": "Customers are forbidden to leave a cart anywhere except the upper-left service bay.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "service_bay": "at(0,1)",
        "outside_service_bay": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "cart_drop_outside_service_bay": {
          "pre": {
            "and": [
              "with_cart",
              "LEAVE_CART",
              "outside_service_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_drop_outside_service_bay"
    }
  },
  {
    "id": "return_cart_to_service_bay",
    "text": "Customers are obliged to bring the cart to the upper-left service bay and leave it there at least once before exiting.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "service_bay": "at(0,1)",
        "cart_parked_at_service_bay": "cartAt(0,1)"
      },
      "events": {
        "service_bay_cart_drop": {
          "pre": {
            "and": [
              "service_bay",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_service_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "service_bay_cart_drop"
    }
  },
  {
    "id": "depart_service_bay_south",
    "text": "After servicing the cart at the upper-left service bay, customers are obliged to depart that bay by moving south, regardless of whether they retake the cart.",
    "abstraction": {
      "state_properties": {
        "service_bay": "at(0,1)",
        "cart_parked_at_service_bay": "cartAt(0,1)",
        "with_cart": "hasCart"
      },
      "events": {
        "service_bay_cart_drop": {
          "pre": {
            "and": [
              "service_bay",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_service_bay"
        },
        "southward_departure_from_service_bay": {
          "pre": {
            "and": [
              "service_bay",
              "S"
            ]
          },
          "post": "at(0,2)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "service_bay_cart_drop",
      "discharge": "southward_departure_from_service_bay"
    }
  },
  {
    "id": "bulky_item_requires_cart_exit",
    "text": "If a customer collects an item from the right-middle bulky-item station, they are obliged to leave the store with the cart.",
    "abstraction": {
      "state_properties": {
        "bulky_item_station": "at(6,4)",
        "with_cart": "hasCart",
        "exit_door": "at(9,5)"
      },
      "events": {
        "bulky_item_loaded_into_cart": {
          "pre": {
            "and": [
              "bulky_item_station",
              "with_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": "with_cart"
        },
        "exit_with_cart": {
          "pre": {
            "and": [
              "exit_door",
              "with_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "bulky_item_loaded_into_cart",
      "discharge": "exit_with_cart"
    }
  },
  {
    "id": "foot_exit_requires_cart_parked",
    "text": "Customers who exit without the cart are forbidden to do so unless the cart is parked at the upper-left service bay.",
    "abstraction": {
      "state_properties": {
        "exit_door": "at(9,5)",
        "with_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        },
        "cart_parked_at_service_bay": "cartAt(0,1)",
        "cart_not_parked_at_service_bay": {
          "not": "cartAt(0,1)"
        }
      },
      "events": {
        "improper_foot_exit": {
          "pre": {
            "and": [
              "exit_door",
              "without_cart",
              "cart_not_parked_at_service_bay",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improper_foot_exit"
    }
  }
]
